import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";

import Headerreg from "../components/Header_reg";

export default function Registro() {
  const [nombre, setNombre] = useState("");
  const [correo, setCorreo] = useState("");
  const [password, setPassword] = useState("");

  const manejarRegistro = async (e) => {
    e.preventDefault();

    if (!nombre || !correo || !password) {
      alert("Por favor completa todos los campos");
      return;
    }

    try {
      // ⬇ Aquí debes colocar tu endpoint de Flask cuando lo tengas
      // const respuesta = await fetch("http://localhost:5000/registro", {
      //   method: "POST",
      //   headers: { "Content-Type": "application/json" },
      //   body: JSON.stringify({ nombre, correo, password }),
      // });

      // const data = await respuesta.json();

      // if (data.success) {
      //   alert("Registro exitoso");
      // } else {
      //   alert(data.message || "Error en el registro");
      // }

      // Temporal mientras conectamos backend:
      alert(`Usuario registrado:\nNombre: ${nombre}\nCorreo: ${correo}`);
    } catch (error) {
      alert("Error de conexión con el servidor");
      console.error(error);
    }
  };

    return (
        <>
            <Headerreg />
            <main>
        <form className="form-registro" onSubmit={manejarRegistro}>
          <h2 className="subtitulo">Crear cuenta</h2>

          <label htmlFor="nombre">Nombre</label>
          <input
            type="text"
            id="nombre"
            value={nombre}
            onChange={(e) => setNombre(e.target.value)}
            placeholder="Ingresa tu nombre"
          />

          <label htmlFor="correo">Correo electrónico</label>
          <input
            type="email"
            id="correo"
            value={correo}
            onChange={(e) => setCorreo(e.target.value)}
            placeholder="Ingresa tu correo"
          />

          <label htmlFor="password">Contraseña</label>
          <input
            type="password"
            id="password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            placeholder="Ingresa tu contraseña"
          />

          <button type="submit">Registrarse</button>
        </form>
      </main>
        </>
    );
}
